# Count by type
types = {}
for line in lines:
    try:
        obj = json.loads(line)
        obj_type = obj.get('type', 'unknown')
        types[obj_type] = types.get(obj_type, 0) + 1
    except:
        pass

print("Types:", types)

# Get all messages
messages = []
for line in lines:
    try:
        msg = json.loads(line)
        if msg.get('type') == 'message':
            messages.append(msg)
    except:
        pass

print(f"\nFound {len(messages)} message entries")

# Check for user vs assistant vs toolResult
